package cz.mh.rallye.rallye_backend.competition;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import cz.mh.rallye.rallye_backend.competition.domain.*;
class GpsParserTest {
 @Test void allRequiredCoordinateForms(){for(String s:new String[]{"50.08745, 14.4206666667","50.08745 N, 14.4206666667 E","N 50° 05.247' E 014° 25.240'","N 50° 05.247 E 014° 25.240","N50 05.247 E014 25.240","N 50 05.247, E 014 25.240","50,08745; 14,4206666667","N 50 05,247 E 014 25,240"}){var p=GpsParser.parse(s);assertEquals(50.08745,p.latitude(),1e-8,s);assertEquals(14.4206666667,p.longitude(),1e-8,s);}var dms=GpsParser.parse("50° 05' 14.8\" N, 14° 25' 14.4\" E");assertEquals(50.0874444444,dms.latitude(),1e-8);assertEquals(-50.08745,GpsParser.parse("S 50 05.247 W 014 25.240").latitude(),1e-8);assertEquals(-14,GpsParser.parse("-50; -14").longitude());}
 @Test void mapUrlsAreParsedWithoutNetwork(){for(String s:new String[]{"https://www.google.com/maps?q=50.087451,14.420671","https://www.google.com/maps/@50.087451,14.420671,15z","https://maps.apple.com/?ll=50.087451,14.420671","https://www.openstreetmap.org/#map=15/50.087451/14.420671","https://mapy.cz/zakladni?x=14.420671&y=50.087451","https://mapy.com/cs/zakladni?x=14.420671&y=50.087451"}){var p=GpsParser.parse(s);assertEquals(50.087451,p.latitude(),1e-8);assertEquals(14.420671,p.longitude(),1e-8);assertEquals("MAP_URL",p.format());}}
 @Test void invalidAmbiguousAndConflictingFormsAreRejected(){for(String s:new String[]{"50,087451,14,420671","N -50 E 14","N 91 E 14","N 90 00.001 E 14","N 50 60 E 14 00","50° 05' 60\" N, 14° 25' 14\" E","https://evil.test/?q=50,14","https://www.google.com/maps?q=Prague","https://maps.apple.com/?ll=1,2&ll=3,4","N +50 W +14"})assertThrows(RaceEvaluator.RuleViolation.class,()->GpsParser.parse(s),s);}
 @Test void integerCoordinatesSignedHemispheresAndCompetingUrls(){assertEquals(50,GpsParser.parse("50,14").latitude());assertEquals(-50,GpsParser.parse("S -50 W -14").latitude());assertEquals(50,GpsParser.parse("E14 N50").latitude());assertThrows(RaceEvaluator.RuleViolation.class,()->GpsParser.parse("https://www.google.com/maps?q=50,14&ll=51,15"));assertThrows(RaceEvaluator.RuleViolation.class,()->GpsParser.parse("https://maps.apple.com.evil.test/?ll=50,14"));}
}
